<template>
  <div class="heritage-view">
    <div class="container">
      <!-- ==================== 页面头部 ==================== -->
      <header class="page-header">
        <!-- 面包屑导航 -->
        <nav class="breadcrumb">
          <router-link to="/" class="breadcrumb-link">首页</router-link>
          <span class="breadcrumb-separator">/</span>
          <span class="breadcrumb-current">荆楚非遗概览</span>
        </nav>
        <h1 class="page-title">荆楚非遗概览</h1>
        <p class="page-desc">探索湖北省丰富的非物质文化遗产，感受千年荆楚文化的独特魅力</p>
      </header>

      <!-- ==================== 筛选区域 ==================== -->
      <div class="filter-bar">
        <!-- 分类筛选下拉 -->
        <div class="filter-item">
          <label class="filter-label">分类</label>
          <select v-model="filters.category" class="filter-select" @change="handleFilterChange">
            <option value="">全部分类</option>
            <option v-for="cat in heritageCategories" :key="cat" :value="cat">{{ cat }}</option>
          </select>
        </div>

        <!-- 级别筛选下拉 -->
        <div class="filter-item">
          <label class="filter-label">级别</label>
          <select v-model="filters.level" class="filter-select" @change="handleFilterChange">
            <option value="">全部级别</option>
            <option value="国家级">国家级</option>
            <option value="省级">省级</option>
            <option value="市级">市级</option>
            <option value="县级">县级</option>
          </select>
        </div>

        <!-- 地区筛选下拉 -->
        <div class="filter-item">
          <label class="filter-label">地区</label>
          <select v-model="filters.region" class="filter-select" @change="handleFilterChange">
            <option value="">全部地区</option>
            <option value="武汉">武汉</option>
            <option value="荆州">荆州</option>
            <option value="黄冈">黄冈</option>
            <option value="十堰">十堰</option>
            <option value="宜昌">宜昌</option>
            <option value="恩施">恩施</option>
            <option value="襄阳">襄阳</option>
            <option value="孝感">孝感</option>
            <option value="咸宁">咸宁</option>
          </select>
        </div>

        <!-- 搜索框 -->
        <div class="filter-item filter-search">
          <input
            v-model="filters.search"
            type="text"
            class="search-input"
            placeholder="搜索非遗项目..."
            @keyup.enter="handleFilterChange"
          />
          <button class="search-btn" @click="handleFilterChange">
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>
          </button>
        </div>

        <!-- 重置筛选按钮 -->
        <button v-if="hasActiveFilters" class="reset-btn" @click="resetFilters">
          重置筛选
        </button>
      </div>

      <!-- ==================== 结果统计 ==================== -->
      <div class="result-stats">
        共 <span class="stats-highlight">{{ totalCount }}</span> 项非遗
        <span v-if="hasActiveFilters" class="filter-tag">(已筛选)</span>
      </div>

      <!-- ==================== 内容区域 ==================== -->
      <!-- 加载状态: 骨架屏 -->
      <div v-if="loading && heritages.length === 0" class="heritage-grid">
        <SkeletonLoader v-for="i in pageSize" :key="i" type="card" />
      </div>

      <!-- 空状态 -->
      <EmptyState
        v-else-if="!loading && heritages.length === 0"
        title="暂无符合条件的非遗项目"
        description="请尝试调整筛选条件或搜索关键词"
        icon="&#x1F50D;"
      >
        <template #action>
          <button class="reset-btn" @click="resetFilters">清除筛选</button>
        </template>
      </EmptyState>

      <!-- 数据展示: 非遗卡片网格 -->
      <div v-else class="heritage-grid">
        <TransitionGroup name="card-fade">
          <HeritageCard
            v-for="item in heritages"
            :key="item.id"
            :data="item"
            class="heritage-card"
          />
        </TransitionGroup>
      </div>

      <!-- ==================== 分页组件 ==================== -->
      <div v-if="totalPages > 1" class="pagination">
        <!-- 上一页 -->
        <button
          class="page-btn"
          :disabled="currentPage === 1"
          @click="goToPage(currentPage - 1)"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"></polyline></svg>
        </button>

        <!-- 页码按钮 -->
        <template v-for="page in displayedPages" :key="page">
          <span v-if="page === '...'" class="page-ellipsis">...</span>
          <button
            v-else
            class="page-btn"
            :class="{ active: page === currentPage }"
            @click="goToPage(page)"
          >
            {{ page }}
          </button>
        </template>

        <!-- 下一页 -->
        <button
          class="page-btn"
          :disabled="currentPage === totalPages"
          @click="goToPage(currentPage + 1)"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg>
        </button>

        <!-- 页码信息 -->
        <span class="page-info">第 {{ currentPage }} / {{ totalPages }} 页</span>
      </div>
    </div>
  </div>
