<script setup>
/**
 * HeritageView.vue - 非遗概览页面
 *
 * 功能:
 * - 页面标题 + 面包屑导航
 * - 多维度筛选区 (分类/级别/地区/搜索)
 * - 响应式网格卡片展示 (4/3/2/1列)
 * - 分页组件
 * - 骨架屏 + 空状态处理
 * - 从URL query参数初始化筛选条件
 */
import { ref, computed, onMounted, watch } from 'vue'
import { useStore } from 'vuex'
import { useRoute, useRouter } from 'vue-router'
import HeritageCard from '@/components/HeritageCard.vue'
import SkeletonLoader from '@/components/SkeletonLoader.vue'
import EmptyState from '@/components/EmptyState.vue'

// Store 和 Router
const store = useStore()
const route = useRoute()
const router = useRouter()

// ==================== 筛选状态 ====================
const filters = ref({
  category: '',
  level: '',
  region: '',
  search: ''
})

// ==================== 分页状态 ====================
const currentPage = ref(1)
const pageSize = 12
const totalCount = computed(() => store.state.heritagesTotal || 0)
const totalPages = computed(() => Math.ceil(totalCount.value / pageSize))

// ==================== 数据 ====================
const loading = computed(() => store.state.loading)
const heritages = computed(() => store.state.heritages)
const heritageCategories = computed(() => store.state.heritageCategories)

// ==================== 计算属性 ====================

/**
 * 判断是否有激活的筛选条件
 */
const hasActiveFilters = computed(() => {
  return filters.value.category || filters.value.level || filters.value.region || filters.value.search
})

/**
 * 计算要显示的页码列表 (支持省略号)
 * 最多显示7个页码: 1 ... 4 5 6 ... 10
 */
const displayedPages = computed(() => {
  const total = totalPages.value
  const current = currentPage.value
  const pages = []

  if (total <= 7) {
    // 页数较少时全部显示
    for (let i = 1; i <= total; i++) pages.push(i)
  } else {
    // 始终显示第一页
    pages.push(1)

    if (current > 3) {
      pages.push('...')
    }

    // 当前页附近的页码
    const start = Math.max(2, current - 1)
    const end = Math.min(total - 1, current + 1)

    for (let i = start; i <= end; i++) {
      pages.push(i)
    }

    if (current < total - 2) {
      pages.push('...')
    }

    // 始终显示最后一页
    pages.push(total)
  }

  return pages
})

// ==================== 方法 ====================

/**
 * 根据当前筛选条件和页码获取非遗数据
 */
const fetchData = async () => {
  const params = {
    page: currentPage.value,
    limit: pageSize
  }
  // 仅添加有值的筛选参数
  if (filters.value.category) params.category = filters.value.category
  if (filters.value.level) params.level = filters.value.level
  if (filters.value.region) params.region = filters.value.region
  if (filters.value.search) params.search = filters.value.search

  try {
    await store.dispatch('fetchHeritages', params)
  } catch (err) {
    console.error('获取非遗列表失败:', err)
  }
}

/**
 * 筛选条件变化时重置到第一页并重新获取数据
 */
const handleFilterChange = () => {
  currentPage.value = 1
  fetchData()
}

/**
 * 跳转到指定页码
 * @param {number} page - 目标页码
 */
const goToPage = (page) => {
  if (page < 1 || page > totalPages.value) return
  currentPage.value = page
  fetchData()
  // 滚动到页面顶部
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

/**
 * 重置所有筛选条件
 */
const resetFilters = () => {
  filters.value = { category: '', level: '', region: '', search: '' }
  currentPage.value = 1
  fetchData()
}

/**
 * 从URL query参数初始化筛选条件
 */
const initFromQuery = () => {
  const { category, level, region, search, page } = route.query
  if (category) filters.value.category = category
  if (level) filters.value.level = level
  if (region) filters.value.region = region
  if (search) filters.value.search = search
  if (page) currentPage.value = parseInt(page) || 1
}

// ==================== 生命周期 ====================
onMounted(async () => {
  // 从URL参数初始化筛选
  initFromQuery()

  // 获取非遗分类列表 (如store中还没有)
  if (heritageCategories.value.length === 0) {
    try {
      await store.dispatch('fetchHeritageCategories')
    } catch (err) {
      console.error('获取分类列表失败:', err)
    }
  }

  // 获取非遗数据
  await fetchData()
})

// 监听路由query变化 (支持从其他页面带参数跳转)
watch(() => route.query, () => {
  initFromQuery()
  fetchData()
}, { deep: true })
</script>

